const q = "INSERT INTO public.os_contracts_queue (queue_type,hubspot_deal_id,queue_date,client_name,drive_link,status,proposal_status_detail) VALUES ('proposal','" + esc(dealId) + "',CURRENT_DATE,'" + esc(d.clientName) + "','" + esc(driveLink) + "','Pending Review','" + esc(statusDetail) + "') ON CONFLICT (hubspot_deal_id,queue_type) DO UPDATE SET client_name = EXCLUDED.client_name, drive_link = EXCLUDED.drive_link, status = EXCLUDED.status, proposal_status_detail = EXCLUDED.proposal_status_detail, queue_date = EXCLUDED.queue_date, updated_at = now();";
return [{ json: { _sql: q } }];

const assoc = $('Fetch Line Item Associations').first().json;
const rows = Array.isArray(assoc?.results) ? assoc.results : Array.isArray(assoc?.data?.results) ? assoc.data.results : [];
const lineItemIds = [...new Set(rows.map((r) => r.toObjectId || r.id).filter(Boolean).map(String))];
return [{ json: { lineItemIds, hasLineItems: lineItemIds.length > 0 } }];

const deal = $('Fetch Deal With Associations').first().json;
const contacts = deal.associations?.contacts?.results || [];
const contactId = contacts.map((c) => c.id).find(Boolean) || '';
return [{ json: { contactId, hasContact: Boolean(contactId) } }];

const root = $('Deal Proposal Stage Webhook').first().json;
const inner = root.webhookBody || root.payload || root.body || root;
const body = inner.body && typeof inner.body === 'object' && !Array.isArray(inner.body) ? inner.body : inner;
const props = body.properties && typeof body.properties === 'object' ? body.properties : {};
const first = (...values) => values.flat().find((v) => v !== undefined && v !== null && String(v).trim());
const mode = String(root.mode || body.mode || inner.mode || '').toLowerCase();
const associatedContactIds = root.associatedContactIds || body.associatedContactIds || inner.associatedContactIds || [];

// This webhook is deal-first. SYS 00 posts HubSpot deal events as { body: { id, properties } }
// without a mode flag, so body.id and properties.hs_object_id must be treated as deal IDs.
const directDealId = first(
  root.dealId,
  body.dealId,
  inner.dealId,
  body.id,
  inner.id,
  props.hs_object_id,
);
const contactId = first(
  root.contactId,
  body.contactId,
  inner.contactId,
  associatedContactIds,
  mode.includes('contact') ? body.id : '',
  mode.includes('contact') ? inner.id : '',
);
return [{ json: { dealId: directDealId ? String(directDealId) : '', contactId: contactId ? String(contactId) : '', hasDealId: Boolean(directDealId), hasContactId: Boolean(contactId) } }];

const assoc = $('Fetch Contact Deal Associations').first().json;
const rows = Array.isArray(assoc?.results) ? assoc.results : Array.isArray(assoc?.data?.results) ? assoc.data.results : [];
const dealId = rows.map((r) => r.toObjectId || r.id).find(Boolean);
return [{ json: { dealId: dealId ? String(dealId) : '', source: 'contact-association' } }];
